-- The provider is handed html_body verbatim, so the old paragraph soup WAS the whole
-- document: no wrapper, no styling, no branding. This gives the reset note a real
-- email shell in the Verdigris palette -- table layout and inline rules for Outlook,
-- a plain-URL fallback for clients that strip the button, and the stored preheader
-- carried as a hidden preview line, since nothing else ever sends it.
UPDATE ap_email_templates
SET html_body = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light only"><meta name="supported-color-schemes" content="light only"><title>Find your way back.</title></head><body style="margin:0;padding:0;background:#f4e4c5;"><div style="display:none;max-height:0;overflow:hidden;opacity:0;">One hour, one link, and your current password works until you use it.&#8203;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f4e4c5" style="background:#f4e4c5;"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;"><tr><td align="left" style="padding:0 4px 18px;font-family:Georgia,''Times New Roman'',serif;font-size:20px;letter-spacing:.14em;text-transform:uppercase;color:#3b1e36;font-weight:700;">Vera Solaro</td></tr><tr><td bgcolor="#fffdf6" style="background:#fffdf6;border:3px solid #2c1810;border-bottom-width:7px;border-radius:14px;padding:34px 32px;"><p style="margin:0 0 10px;font-family:Georgia,''Times New Roman'',serif;font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:#c6491f;font-weight:700;">Your sittings</p><h1 style="margin:0 0 22px;font-family:Georgia,''Times New Roman'',serif;font-size:32px;line-height:1.15;color:#3b1e36;font-weight:700;">Find your way back.</h1><p style="margin:0 0 16px;font-family:Georgia,''Times New Roman'',serif;font-size:16px;line-height:1.6;color:#2c1810;">Dear {{customerName}},</p><p style="margin:0 0 26px;font-family:Georgia,''Times New Roman'',serif;font-size:16px;line-height:1.6;color:#2c1810;">Somebody asked for a new password on your account. If that was you, the button below sets one.</p><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 24px;"><tr><td bgcolor="#c6491f" style="background:#c6491f;border:3px solid #2c1810;border-radius:999px;"><a href="{{resetUrl}}" style="display:inline-block;padding:14px 30px;font-family:Georgia,''Times New Roman'',serif;font-size:15px;letter-spacing:.1em;text-transform:uppercase;color:#fffdf6;text-decoration:none;font-weight:700;">Choose a new password &rarr;</a></td></tr></table><p style="margin:0 0 24px;font-family:Georgia,''Times New Roman'',serif;font-size:13px;line-height:1.6;color:#7a5a44;">If the button will not open, paste this into the address bar:<br><a href="{{resetUrl}}" style="color:#c6491f;word-break:break-all;">{{resetUrl}}</a></p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 22px;"><tr><td style="border-top:2px solid #f4e4c5;padding-top:18px;"><p style="margin:0 0 4px;font-family:Georgia,''Times New Roman'',serif;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#7a5a44;font-weight:700;">Good for</p><p style="margin:0;font-family:Georgia,''Times New Roman'',serif;font-size:16px;color:#2c1810;">One hour from the moment this was sent</p></td></tr></table><p style="margin:0 0 20px;font-family:Georgia,''Times New Roman'',serif;font-size:15px;line-height:1.6;color:#2c1810;">If it wasn''t you, do nothing whatsoever. Your current password still works and nothing has changed.</p><p style="margin:0;font-family:Georgia,''Times New Roman'',serif;font-size:16px;color:#3b1e36;font-style:italic;">Vera</p></td></tr><tr><td align="left" style="padding:20px 6px 0;font-family:Georgia,''Times New Roman'',serif;font-size:12px;line-height:1.7;color:#7a5a44;">Via delle Stelle 12, Trieste &middot; This link was asked for from the sign-in page and can be used once.</td></tr></table></td></tr></table></body></html>',
    text_body = 'Dear {{customerName}}, Somebody asked for a new password on your account. If that was you, the link below sets one. Choose a new password → {{resetUrl}} Good for One hour from the moment this was sent If it wasn''t you, do nothing whatsoever. Your current password still works and nothing has changed. Vera Via delle Stelle 12, Trieste · This link was asked for from the sign-in page and can be used once.',
    updated_by = 'system',
    updated_at = '2026-08-19T00:00:00.000Z'
WHERE key = 'customer_password_reset_en';
